using TasiaCraft;
public static class AlignmentTest {
 static int passed,before,after;static string root,log;static LivePreview live;
 static void Require(bool ok,string label){if(!ok)throw new Exception(label);File.AppendAllText(log,"PASS "+label+Environment.NewLine);passed++;}
 static bool Near(double a,double b){return Math.Abs(a-b)<.001;}
 static void Rectangle(Rect actual,double x,double y,double w,double h,string label){Require(Near(actual.X,x)&&Near(actual.Y,y)&&Near(actual.Width,w)&&Near(actual.Height,h),label+" actual="+actual);}
 static void VectorIs(Vector actual,double x,double y,string label){Require(Near(actual.X,x)&&Near(actual.Y,y),label);}
 static void Reject(Action action,string label){bool failed=false;try{action();}catch(ArgumentException){failed=true;}Require(failed,label);}
 static byte[] Pixels(){live.UpdateLayout();var bitmap=new RenderTargetBitmap(200,100,96,96,PixelFormats.Pbgra32);bitmap.Render(live.Stage);var pixels=new byte[200*100*4];bitmap.CopyPixels(pixels,200*4,0);return pixels;}
 static bool Red(byte[] p,int x,int y){int i=(y*200+x)*4;return p[i+2]>230&&p[i+1]<30&&p[i]<30;}
 static bool Black(byte[] p,int x,int y){int i=(y*200+x)*4;return p[i+2]<20&&p[i+1]<20&&p[i]<20;}
 static object Field(object o,string name){return o.GetType().GetField(name,BindingFlags.Instance|BindingFlags.NonPublic).GetValue(o);}
 static void Call(object o,string name,params object[] args){o.GetType().GetMethod(name,BindingFlags.Instance|BindingFlags.NonPublic).Invoke(o,args);}
 static CanvasSnapResult Snap(double x,double y){return (CanvasSnapResult)typeof(LivePreview).GetMethod("SnapMove",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(live,new object[]{x,y});}
 static byte[] DisplayPixels(){live.UpdateLayout();int w=(int)live.ActualWidth,h=(int)live.ActualHeight;var b=new RenderTargetBitmap(w,h,96,96,PixelFormats.Pbgra32);b.Render(live);var p=new byte[w*h*4];b.CopyPixels(p,w*4,0);return p;}
 static async Task Integration(Media media){
  var p=new Project{Width=200,Height=100};p.Media.Add(media);var moving=new Clip{MediaId=media.Id,NativeSize=true,Duration=1};p.Clips.Add(moving);live.SetProject(p);live.Seek(.2);live.SetSelection(moving);await Task.Delay(40);
  foreach(double zoom in new[]{1.0,2.0,4.0}){live.SetViewZoom(zoom);live.UpdateLayout();await Task.Delay(20);var t=live.Stage.TransformToAncestor(live);double scale=(t.Transform(new Point(1,0))-t.Transform(new Point())).Length;double five=5/scale,seven=7/scale;var snap=Snap(five,five);Require(Near(snap.DeltaX,-five),"five logical pixels snap at zoom "+zoom+" scale="+scale+" delta="+snap.DeltaX+","+snap.DeltaY+" expected="+(-five));snap=Snap(seven,seven);Require(!snap.GuideX.HasValue,"seven logical pixels stay free at zoom "+zoom);}
  live.SetViewZoom(4);live.UpdateLayout();var target=new Clip{MediaId=media.Id,NativeSize=true,Duration=1,Track=1,X=14,Y=14};p.Clips.Add(target);live.SetProject(p);live.Seek(.2);live.SetSelection(moving);live.UpdateLayout();await Task.Delay(20);var near=Snap(13,13);Require(Near(near.DeltaX,1)&&Near(near.DeltaY,1),"active visible layer offers edge and center snapping");p.HiddenTracks.Add(1);near=Snap(13,13);Require(!near.GuideX.HasValue&&!near.GuideY.HasValue,"hidden target omitted from snapping");p.HiddenTracks.Clear();target.Start=2;live.Refresh();near=Snap(13,13);Require(!near.GuideX.HasValue&&!near.GuideY.HasValue,"inactive target omitted from snapping");target.Start=0;live.Refresh();live.SetCanvasSnapping(false);near=Snap(13,13);Require(!near.GuideX.HasValue&&!near.GuideY.HasValue,"disabled canvas snapping returns free movement");live.SetCanvasSnapping(true);
  live.SetSelection(null);var guide=Field(live,"alignmentGuides");byte[] stage=Pixels(),display=DisplayPixels();Call(guide,"SetGuides",(double?)100,(double?)50);await Task.Delay(30);byte[] withGuide=DisplayPixels();Require(!display.SequenceEqual(withGuide),"transient guides visibly render on the display");Require(stage.SequenceEqual(Pixels()),"visible guide pixels are absent from project-sized Stage render");Require(!((UIElement)guide).IsHitTestVisible,"guides do not intercept editing input");live.SetCanvasSnapping(false);await Task.Delay(20);Require(display.SequenceEqual(DisplayPixels()),"disabling snapping clears displayed guides");live.SetCanvasSnapping(true);Call(guide,"SetGuides",(double?)100,(double?)50);live.SetSelection(moving);live.SetSelection(null);await Task.Delay(20);Require(display.SequenceEqual(DisplayPixels()),"selection changes clear guides");Call(guide,"SetGuides",(double?)100,(double?)50);live.SetPanMode(true);await Task.Delay(20);Require(display.SequenceEqual(DisplayPixels()),"pan mode clears guides");live.SetPanMode(false);
  var editor=new Editor();typeof(Editor).GetField("project",BindingFlags.NonPublic|BindingFlags.Instance).SetValue(editor,p);typeof(Editor).GetField("selected",BindingFlags.NonPublic|BindingFlags.Instance).SetValue(editor,moving);Call(editor,"Refresh");var canvas=(LivePreview)Field(editor,"live");canvas.SetSelection(moving);moving.X=20;moving.Y=10;canvas.Refresh();Require(canvas.AlignSelection("Left"),"real editor alignment changes selection");Require(((System.Collections.Generic.Stack<string>)Field(editor,"undo")).Count==1,"real editor alignment creates one undo checkpoint");Call(editor,"Undo");var undone=(Project)Field(editor,"project");Require(Near(undone.Clips[0].X,20)&&Near(undone.Clips[0].Y,10),"real editor undo restores pre-alignment transform");Call(editor,"Redo");var redone=(Project)Field(editor,"project");Require(Near(redone.Clips[0].X,-60)&&Near(redone.Clips[0].Y,10),"real editor redo restores aligned transform");canvas.Dispose();typeof(Editor).GetField("dirty",BindingFlags.NonPublic|BindingFlags.Instance).SetValue(editor,false);editor.Close();
 }
 static void Geometry(){
  var c=new Clip{Duration=1};Rectangle(CanvasAlignment.Bounds(c,160,80,200,100),20,10,160,80,"uncropped source centered independently of project aspect");c.X=7;c.Y=-3;c.Scale=.5;c.CropLeft=.25;c.CropTop=.125;c.CropBottom=.25;c.Rotation=90;Rectangle(CanvasAlignment.Bounds(c,160,80,200,100),97,27,25,60,"cropped rotated scaled bounds preserve full-source pivot");c.Rotation=180;Rectangle(CanvasAlignment.Bounds(c,160,80,200,100),67,37,60,25,"180 degree asymmetric crop bounds");
  var moving=new Rect(20,30,40,20);var result=CanvasAlignment.Snap(moving,new[]{new Rect(64,54,40,20)},4);Require(Near(result.DeltaX,4)&&Near(result.DeltaY,4)&&result.GuideX.HasValue&&Near(result.GuideX.Value,64)&&result.GuideY.HasValue&&Near(result.GuideY.Value,54),"inclusive threshold snaps independent axes to nearby edges");result=CanvasAlignment.Snap(moving,new[]{new Rect(64,54,40,20)},3.999);Require(result.DeltaX==0&&result.DeltaY==0&&!result.GuideX.HasValue&&!result.GuideY.HasValue,"outside threshold does not snap or expose stale guides");result=CanvasAlignment.Snap(moving,new[]{new Rect(64,100,40,20),new Rect(62,100,40,20)},4);Require(Near(result.DeltaX,2)&&Near(result.GuideX.Value,62),"nearest target wins over earlier farther target");result=CanvasAlignment.Snap(moving,new[]{new Rect(64,100,40,20),new Rect(56,100,40,20)},4);Require(Near(result.DeltaX,4),"first target wins deterministic equal distance tie");result=CanvasAlignment.Snap(moving,new[]{new Rect(56,100,40,20),new Rect(64,100,40,20)},4);Require(Near(result.DeltaX,-4),"reversed equal distance targets preserve first-target tie rule");result=CanvasAlignment.Snap(moving,new[]{new Rect(60,100,40,20)},0);Require(result.DeltaX==0&&result.GuideX==60,"zero tolerance recognizes exact edge alignment");result=CanvasAlignment.Snap(moving,new Rect[0],4);Require(result.DeltaX==0&&result.DeltaY==0&&!result.GuideX.HasValue&&!result.GuideY.HasValue,"empty targets return no guides or translation");
  var rect=new Rect(25,40,50,20);VectorIs(CanvasAlignment.Align(rect,200,100,"Left"),-25,0,"align left reaches project edge");VectorIs(CanvasAlignment.Align(rect,200,100,"Horizontal center"),50,0,"horizontal center uses visible bounds center");VectorIs(CanvasAlignment.Align(rect,200,100,"Right"),125,0,"align right reaches project edge");VectorIs(CanvasAlignment.Align(rect,200,100,"Top"),0,-40,"align top reaches project edge");VectorIs(CanvasAlignment.Align(rect,200,100,"Vertical center"),0,0,"already centered axis yields zero translation");VectorIs(CanvasAlignment.Align(rect,200,100,"Bottom"),0,40,"align bottom reaches project edge");
  Reject(()=>CanvasAlignment.Snap(rect,new[]{rect},double.NaN),"NaN snap tolerance rejected");Reject(()=>CanvasAlignment.Snap(rect,new[]{rect},-1),"negative snap tolerance rejected");Reject(()=>CanvasAlignment.Snap(Rect.Empty,new[]{rect},4),"nonfinite moving bounds rejected");Reject(()=>CanvasAlignment.Snap(rect,new[]{Rect.Empty},4),"nonfinite target bounds rejected");Reject(()=>CanvasAlignment.Align(Rect.Empty,200,100,"Left"),"nonfinite align bounds rejected");Reject(()=>CanvasAlignment.Align(rect,0,100,"Left"),"zero project dimension rejected");Reject(()=>CanvasAlignment.Align(rect,200,100,"Unknown"),"unknown alignment rejected");Reject(()=>CanvasAlignment.Bounds(c,double.NaN,80,200,100),"nonfinite source dimension rejected");Reject(()=>CanvasAlignment.Bounds(c,-1,80,200,100),"negative source dimension rejected");c.Scale=double.NaN;Reject(()=>CanvasAlignment.Bounds(c,160,80,200,100),"nonfinite clip scale rejected");
 }
 [STAThread]public static void Main(string[] args){root=args[0];Directory.CreateDirectory(root);log=Path.Combine(root,"results.txt");File.WriteAllText(log,"");var app=new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};live=new LivePreview();var window=new Window{Title="TatsiaCraft isolated canvas alignment acceptance",Width=700,Height=460,Content=live};window.Loaded+=async(s,e)=>{try{
  Geometry();string source=Path.Combine(root,"source.png");using(var b=new System.Drawing.Bitmap(80,40)){using(var g=System.Drawing.Graphics.FromImage(b))g.Clear(System.Drawing.Color.Red);b.Save(source,System.Drawing.Imaging.ImageFormat.Png);}var media=new Media{Path=source,Kind="image",Name="source.png",Duration=5,Width=80,Height=40};var p=new Project{Width=200,Height=100};p.Media.Add(media);var c=new Clip{MediaId=media.Id,NativeSize=true,Duration=1,X=20,Y=10};p.Clips.Add(c);live.SetProject(p);live.Seek(.2);live.SetSelection(c);live.BeforeEdit+=()=>before++;live.AfterEdit+=()=>after++;await Task.Delay(80);
  live.SetCanvasSnapping(false);Require(!live.CanvasSnappingEnabled,"canvas snapping can be disabled");live.SetCanvasSnapping(true);Require(live.CanvasSnappingEnabled,"canvas snapping can be enabled");Require(before==0&&after==0,"snapping preference does not create document checkpoints");string preserved=new JavaScriptSerializer().Serialize(c);Require(live.AlignSelection("Left"),"align selected visible image reports a change");Require(c.X==-60&&c.Y==10,"align selection moves only requested axis to project left");Require(before==1&&after==1,"alignment creates exactly one before and after edit callback");c.X=20;Require(new JavaScriptSerializer().Serialize(c)==preserved,"alignment preserves selection identity timing crop scale rotation and all other properties");c.X=-60;Require(!live.AlignSelection("Left")&&before==1&&after==1,"already aligned selection is a no-op without checkpoint");
  live.SetSelection(null);live.Refresh();await Task.Delay(80);var pixels=Pixels();Require(Red(pixels,10,60)&&Black(pixels,120,60),"preview pixels show aligned image at left and uncovered center-right");string saved=Path.Combine(root,"aligned.tasia");Engine.Save(p,saved);var loaded=Engine.Load(saved).Clips[0];Require(loaded.X==-60&&loaded.Y==10&&loaded.NativeSize,"aligned placement survives save and reopen");string output=Path.Combine(root,"aligned.mp4"),png=Path.Combine(root,"aligned.png");Engine.Render(p,output,null);Engine.Run("ffmpeg","-y -v error -ss 0.2 -i "+Engine.Quote(output)+" -frames:v 1 -threads 1 "+Engine.Quote(png));using(var b=new System.Drawing.Bitmap(png)){var red=b.GetPixel(10,60);var black=b.GetPixel(120,60);Require(red.R>230&&red.G<30&&red.B<30&&black.R<20&&black.G<20&&black.B<20,"decoded export pixels agree with aligned preview placement");}
  live.SetSelection(c);p.LockedTracks.Add(c.Track);Require(!live.AlignSelection("Right"),"locked track rejects alignment");p.LockedTracks.Clear();p.HiddenTracks.Add(c.Track);Require(!live.AlignSelection("Right"),"hidden track rejects alignment");p.HiddenTracks.Clear();live.Seek(1);Require(!live.AlignSelection("Right"),"inactive clip rejects alignment");live.Seek(.2);c.Animate=true;Require(!live.AlignSelection("Right"),"animated clip rejects alignment");c.Animate=false;live.SetSelection(null);Require(!live.AlignSelection("Right"),"missing selection rejects alignment");Require(before==1&&after==1,"guarded alignment paths create no edit callbacks");
  var audio=new Media{Path=source,Name="audio fixture metadata",Kind="audio",Duration=5,HasAudio=true};p.Media.Add(audio);var ac=new Clip{MediaId=audio.Id,Duration=1,Track=1};p.Clips.Add(ac);live.SetProject(p);live.SetSelection(ac);Require(!live.AlignSelection("Left"),"audio clip rejects canvas alignment");Require(before==1&&after==1,"audio guard creates no checkpoint");var cropped=new Clip{MediaId=media.Id,NativeSize=true,Duration=1,Scale=.5,Rotation=90,X=7,Y=-3,CropLeft=.25,CropTop=.125,CropBottom=.25};var rotatedProject=new Project{Width=200,Height=100};rotatedProject.Media.Add(media);rotatedProject.Clips.Add(cropped);live.SetProject(rotatedProject);live.Seek(.2);live.SetSelection(cropped);Require(live.AlignSelection("Left")&&Near(cropped.X,-95)&&Near(cropped.Y,-3),"actual alignment uses cropped rotated scaled visible bounds");Require(cropped.CropLeft==.25&&cropped.CropTop==.125&&cropped.CropBottom==.25&&cropped.Scale==.5&&cropped.Rotation==90,"alignment preserves asymmetric crop scale and rotation");Require(before==2&&after==2,"cropped rotated alignment creates one edit callback pair");await Integration(media);live.Dispose();File.AppendAllText(log,"PASS total "+passed+Environment.NewLine);app.Shutdown(0);
 }catch(Exception ex){File.AppendAllText(log,"FAIL "+ex+Environment.NewLine);live.Dispose();app.Shutdown(1);}};app.Run(window);}
}



